metadata.ans:document:
{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "plain",
    "theme": "default",
    "headStyle": "title",
    "locale": "en"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "event",
        "text": "When the election timer runs out"
      },
      "body": [
        {
          "id": "b1",
          "kind": "if",
          "text": "Am I the leader?",
          "yes": {
            "id": "r1",
            "body": [
              {
                "id": "b2",
                "kind": "process",
                "text": ""
              }
            ]
          },
          "no": {
            "id": "r2",
            "body": [
              {
                "id": "b3",
                "kind": "process",
                "text": "Become a candidate"
              },
              {
                "id": "b4",
                "kind": "process",
                "text": "Increase the term by one"
              },
              {
                "id": "b5",
                "kind": "process",
                "text": "Vote for myself\n(votes = 1)"
              },
              {
                "id": "b6",
                "kind": "process",
                "text": "Reset the election timer to a random time"
              },
              {
                "id": "b7",
                "kind": "process",
                "text": "Send a vote request to every peer\n(term, index and term of my last entry)"
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "event",
        "text": "When a vote request arrives"
      },
      "body": [
        {
          "id": "b8",
          "kind": "if",
          "text": "Request term > my term?",
          "yes": {
            "id": "r3",
            "body": [
              {
                "id": "b9",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d10"
                },
                "args": "",
                "result": ""
              }
            ]
          },
          "no": {
            "id": "r4",
            "body": [
              {
                "id": "b10",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b11",
          "kind": "if",
          "text": "Request term < my term?",
          "yes": {
            "id": "r5",
            "body": [
              {
                "id": "b12",
                "kind": "process",
                "text": "Reply: rejected"
              }
            ]
          },
          "no": {
            "id": "r6",
            "body": [
              {
                "id": "b13",
                "kind": "if",
                "text": "Not voted yet in this term,\nor already voted for this candidate?",
                "yes": {
                  "id": "r7",
                  "body": [
                    {
                      "id": "b14",
                      "kind": "if",
                      "text": "Is the candidate's log as up to date as mine?",
                      "yes": {
                        "id": "r8",
                        "body": [
                          {
                            "id": "b15",
                            "kind": "process",
                            "text": "Note that I voted for this candidate"
                          },
                          {
                            "id": "b16",
                            "kind": "process",
                            "text": "Reset the election timer"
                          },
                          {
                            "id": "b17",
                            "kind": "process",
                            "text": "Reply: vote granted"
                          }
                        ]
                      },
                      "no": {
                        "id": "r9",
                        "body": [
                          {
                            "id": "b18",
                            "kind": "process",
                            "text": "Reply: rejected"
                          }
                        ]
                      }
                    }
                  ]
                },
                "no": {
                  "id": "r10",
                  "body": [
                    {
                      "id": "b19",
                      "kind": "process",
                      "text": "Reply: rejected"
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d3",
      "head": {
        "kind": "event",
        "text": "When a vote reply arrives"
      },
      "body": [
        {
          "id": "b20",
          "kind": "if",
          "text": "Reply term > my term?",
          "yes": {
            "id": "r11",
            "body": [
              {
                "id": "b21",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d10"
                },
                "args": "",
                "result": ""
              }
            ]
          },
          "no": {
            "id": "r12",
            "body": [
              {
                "id": "b22",
                "kind": "if",
                "text": "Still a candidate, and a vote\nfor me in this term?",
                "yes": {
                  "id": "r13",
                  "body": [
                    {
                      "id": "b23",
                      "kind": "process",
                      "text": "Add one to the votes"
                    },
                    {
                      "id": "b24",
                      "kind": "if",
                      "text": "Do the votes make a majority?",
                      "yes": {
                        "id": "r14",
                        "body": [
                          {
                            "id": "b25",
                            "kind": "process",
                            "text": "Become the leader"
                          },
                          {
                            "id": "b26",
                            "kind": "process",
                            "text": "Set each peer's next index\nto my last index + 1"
                          },
                          {
                            "id": "b27",
                            "kind": "call",
                            "target": {
                              "kind": "local",
                              "diagram": "d8"
                            },
                            "args": "",
                            "result": ""
                          }
                        ]
                      },
                      "no": {
                        "id": "r15",
                        "body": [
                          {
                            "id": "b28",
                            "kind": "process",
                            "text": ""
                          }
                        ]
                      }
                    }
                  ]
                },
                "no": {
                  "id": "r16",
                  "body": [
                    {
                      "id": "b29",
                      "kind": "process",
                      "text": ""
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d4",
      "head": {
        "kind": "event",
        "text": "When the heartbeat timer runs out"
      },
      "body": [
        {
          "id": "b30",
          "kind": "if",
          "text": "Am I the leader?",
          "yes": {
            "id": "r17",
            "body": [
              {
                "id": "b31",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d8"
                },
                "args": "",
                "result": ""
              }
            ]
          },
          "no": {
            "id": "r18",
            "body": [
              {
                "id": "b32",
                "kind": "process",
                "text": ""
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d5",
      "head": {
        "kind": "event",
        "text": "When a client request arrives"
      },
      "body": [
        {
          "id": "b33",
          "kind": "if",
          "text": "Am I the leader?",
          "yes": {
            "id": "r19",
            "body": [
              {
                "id": "b34",
                "kind": "process",
                "text": "Append the command to the log\nas a new entry of this term"
              },
              {
                "id": "b35",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d8"
                },
                "args": "",
                "result": ""
              }
            ]
          },
          "no": {
            "id": "r20",
            "body": [
              {
                "id": "b36",
                "kind": "process",
                "text": "Tell the client the leader's address"
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d6",
      "head": {
        "kind": "event",
        "text": "When a log replication request arrives"
      },
      "body": [
        {
          "id": "b37",
          "kind": "if",
          "text": "Request term < my term?",
          "yes": {
            "id": "r21",
            "body": [
              {
                "id": "b38",
                "kind": "process",
                "text": "Reply: failure\n(with my term)"
              }
            ]
          },
          "no": {
            "id": "r22",
            "body": [
              {
                "id": "b39",
                "kind": "if",
                "text": "Request term > my term,\nor am I a candidate?",
                "yes": {
                  "id": "r23",
                  "body": [
                    {
                      "id": "b40",
                      "kind": "call",
                      "target": {
                        "kind": "local",
                        "diagram": "d10"
                      },
                      "args": "",
                      "result": ""
                    }
                  ]
                },
                "no": {
                  "id": "r24",
                  "body": [
                    {
                      "id": "b41",
                      "kind": "process",
                      "text": ""
                    }
                  ]
                }
              },
              {
                "id": "b42",
                "kind": "process",
                "text": "Reset the election timer"
              },
              {
                "id": "b43",
                "kind": "if",
                "text": "Do the previous entry's index and term match my log?",
                "yes": {
                  "id": "r25",
                  "body": [
                    {
                      "id": "b44",
                      "kind": "process",
                      "text": "Delete my entries from the first conflict on"
                    },
                    {
                      "id": "b45",
                      "kind": "process",
                      "text": "Append the new entries to the log"
                    },
                    {
                      "id": "b46",
                      "kind": "if",
                      "text": "Leader's commit index > mine?",
                      "yes": {
                        "id": "r26",
                        "body": [
                          {
                            "id": "b47",
                            "kind": "process",
                            "text": "Raise my commit index\n(to the smaller of the leader's commit index\nand my last index)"
                          },
                          {
                            "id": "b48",
                            "kind": "call",
                            "target": {
                              "kind": "local",
                              "diagram": "d9"
                            },
                            "args": "",
                            "result": ""
                          }
                        ]
                      },
                      "no": {
                        "id": "r27",
                        "body": [
                          {
                            "id": "b49",
                            "kind": "process",
                            "text": ""
                          }
                        ]
                      }
                    },
                    {
                      "id": "b50",
                      "kind": "process",
                      "text": "Reply: success"
                    }
                  ]
                },
                "no": {
                  "id": "r28",
                  "body": [
                    {
                      "id": "b51",
                      "kind": "process",
                      "text": "Reply: failure"
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d7",
      "head": {
        "kind": "event",
        "text": "When a log replication reply arrives"
      },
      "body": [
        {
          "id": "b52",
          "kind": "if",
          "text": "Reply term > my term?",
          "yes": {
            "id": "r29",
            "body": [
              {
                "id": "b53",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d10"
                },
                "args": "",
                "result": ""
              }
            ]
          },
          "no": {
            "id": "r30",
            "body": [
              {
                "id": "b54",
                "kind": "if",
                "text": "Success?",
                "yes": {
                  "id": "r31",
                  "body": [
                    {
                      "id": "b55",
                      "kind": "process",
                      "text": "Raise the peer's match index and next index"
                    },
                    {
                      "id": "b56",
                      "kind": "if",
                      "text": "Is an entry of this term held by a majority\nnot committed yet?",
                      "yes": {
                        "id": "r32",
                        "body": [
                          {
                            "id": "b57",
                            "kind": "process",
                            "text": "Raise the commit index up to it"
                          },
                          {
                            "id": "b58",
                            "kind": "call",
                            "target": {
                              "kind": "local",
                              "diagram": "d9"
                            },
                            "args": "",
                            "result": ""
                          }
                        ]
                      },
                      "no": {
                        "id": "r33",
                        "body": [
                          {
                            "id": "b59",
                            "kind": "process",
                            "text": ""
                          }
                        ]
                      }
                    }
                  ]
                },
                "no": {
                  "id": "r34",
                  "body": [
                    {
                      "id": "b60",
                      "kind": "process",
                      "text": "Lower the peer's next index by one\n(it is sent again at the next heartbeat)"
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d8",
      "head": {
        "kind": "method",
        "text": "Send the log to every peer"
      },
      "body": [
        {
          "id": "b61",
          "kind": "while",
          "text": "While a peer is left to send to",
          "body": [
            {
              "id": "b62",
              "kind": "process",
              "text": "Pick the entries for that peer\n(from its next index to the end,\nor none for a heartbeat)"
            },
            {
              "id": "b63",
              "kind": "process",
              "text": "Send a log replication request\n(term, previous index and term,\nentries, commit index)"
            }
          ]
        }
      ]
    },
    {
      "id": "d9",
      "head": {
        "kind": "method",
        "text": "Apply committed entries to the state machine"
      },
      "body": [
        {
          "id": "b64",
          "kind": "while",
          "text": "applied index < commit index",
          "body": [
            {
              "id": "b65",
              "kind": "process",
              "text": "Increase the applied index by one"
            },
            {
              "id": "b66",
              "kind": "process",
              "text": "Apply that entry's command to the state machine"
            },
            {
              "id": "b67",
              "kind": "if",
              "text": "Am I the leader?",
              "yes": {
                "id": "r35",
                "body": [
                  {
                    "id": "b68",
                    "kind": "process",
                    "text": "Reply to the client with the result"
                  }
                ]
              },
              "no": {
                "id": "r36",
                "body": [
                  {
                    "id": "b69",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            }
          ]
        }
      ]
    },
    {
      "id": "d10",
      "head": {
        "kind": "method",
        "text": "Step down to follower"
      },
      "body": [
        {
          "id": "b70",
          "kind": "if",
          "text": "Other side's term > my term?",
          "yes": {
            "id": "r37",
            "body": [
              {
                "id": "b71",
                "kind": "process",
                "text": "Raise my term to the other side's term"
              },
              {
                "id": "b72",
                "kind": "process",
                "text": "Clear my vote for this term"
              }
            ]
          },
          "no": {
            "id": "r38",
            "body": [
              {
                "id": "b73",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b74",
          "kind": "process",
          "text": "Become a follower"
        }
      ]
    }
  ],
  "view": {
    "folded": [],
    "opened": [],
    "bands": true,
    "resultSymbol": "←"
  }
}
